%
% LD2_KarolisSilaika.m
% Karolis Silaika
% Ef-25/1
% 2026-09-16
%
clear
v1 = -pi/2 : 0.5 : 3*pi;
v2 = v1.^2;
v3 = sin(v1+v2);
v4 = (v3 - mean(v3))';

disp('a) v1 ='); disp(v1) %[output:59c08a32]
disp('b) v2 ='); disp(v2) %[output:3cd4cdf6]
disp('c) v3 ='); disp(v3) %[output:721a3ab5]
disp('d) v4 ='); disp(v4) %[output:5e4a2d26]

Z = rand(3,3);
Z(:,2)=[];
ZT = Z';

disp('a) Z =');disp(Z) %[output:0f0f2e12]
disp('b) ZT ='); disp(ZT) %[output:6968af73]


A = 4;
f = 3;    
sigma = 1;  
U1 = 0.5;   
U2 = 2.5; 

t = 0 : 0.002 : 1.5;
s = A * sin( 2 * pi * f * t );
n = sigma * randn( size(t) );
x = s + n;

xa = x( x > U1 );
xb = x;
xb(abs(xb) < U2) = 0;
c = length(x);
d = length(xa);

emax = max(xb);
emin = min(xb);

disp('a) xa =');disp(xa) %[output:9ff1767c]
disp('b) xb =');disp(xb) %[output:68be6077]
disp('c) c=');disp(c) %[output:96a67094]
disp('d) d =');disp(d) %[output:93aa353b]
disp('e) emax=');disp(emax) %[output:23005f50]
disp('f)emin =');disp(emin) %[output:3c66356c]

%%Papildoma uzduotis

A = input('Įveskite vektorių A = [a1,1, a1,2, ..., a1,n]: ');
B = A(2:2:end);
ilgis = length(A);
if mod(ilgis,2) == 0
    C = A(end-1:-2:1);    
else
    C = A(end:-2:1);         
end
disp('a) A =');disp(A) %[output:27b5fd66]
disp('b) B =');disp(B) %[output:2c0bead4]
disp('c) C =');disp(C) %[output:87a77f94]

